from taf.gnb.oam.coam.cu.services.internal.pm.http_client_v1 import PMv1HttpClient
from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh()
class PMv1:
    """
    IMPORTANT: This component has been removed, PMv2 should be used starting from 26R1
    """
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = PMv1HttpClient(base_url=con_details.base_url,
                                           connection_alias=con_details.alias)

    def get_measurement_info(self, measurement_id):
        return self.local_client.get_measurement_info(measurement_id=measurement_id)

    def get_counter(self, measurement_id, dimension_dist_name, counter_id, timeout=30, **kwargs):
        return self.local_client.get_counter(measurement_id=measurement_id,
                                             dimension_dist_name=dimension_dist_name,
                                             counter_id=counter_id,
                                             timeout=timeout,
                                             **kwargs)

    def get_counter_info(self, counter_id, measurement_id):
        return self.local_client.get_counter_info(counter_id=counter_id, measurement_id=measurement_id)
